-- Additions only: no existing lesson bodies, student work, ratings, or class releases are rewritten.
DO $install$
DECLARE item jsonb; target jsonb; l public.lessons; found_target public.learning_targets; existing_id uuid;
  result jsonb; set_id uuid; ids jsonb; blocks jsonb; terms jsonb; windows_before text; old_lessons_before text;
  additions jsonb := $payload$[{"youtubeId":"fmjVsKsU9Sw","sequence":9,"lessonId":"e8c4a169-e774-4b75-87df-5bec72d9a61f","target":{"id":"1b14077c-9c25-458b-a568-84eb1bd9ba8d","slug":"foundations.graph-scales","statement":"I can choose uniform graph scales that fit the data, label axes with quantities and units, and locate points.","domain":"skill","unit_id":"unit-1","program":"physics","content_strand":"foundations","order_index":9},"title":"Setting a graph scale","slug":"video-9-setting-a-graph-scale","duration":242,"description":"How do you choose a readable scale that fits all your data?","document":{"schemaVersion":1,"presentation":"physics-path","dayType":"STANDARD","learningPath":{"version":1,"kind":"lesson","focus":"How do you choose a readable scale that fits all your data?","targetSlugs":["foundations.graph-scales"],"foundations":false},"blocks":[{"id":"video-fmjVsKsU9Sw","type":"instruction_video","youtubeId":"fmjVsKsU9Sw","title":"Setting a graph scale","summary":"Put time on the horizontal axis and position on the vertical axis. Divide each data range by its available squares, then round up to a convenient step such as 1, 2, or 5 times a power of ten. Multiply back to check that the data fits. Keep equal intervals on each axis, label quantities and units, and plot the data.","durationSeconds":242,"targetId":"foundations.graph-scales","workshop":{"stage":"Watch & understand","pageBreakBefore":true}},{"id":"scope-fmjVsKsU9Sw","type":"prose","markdown":"Choose, check, and label uniform graph scales and locate a point using them."},{"id":"vocabulary-fmjVsKsU9Sw","type":"vocab","terms":[{"term":"axis","definition":"A reference line on a graph that shows a quantity, its unit, and a scale."},{"term":"range","definition":"The span from the lowest to the highest value to be shown on an axis."},{"term":"scale","definition":"The amount of a quantity represented by one step or square on an axis."},{"term":"uniform interval","definition":"An equal numerical change for every equal step on an axis."},{"term":"coordinate","definition":"One value used to locate a point along a graph axis."}],"referencePanel":true},{"id":"worked-fmjVsKsU9Sw","type":"worked_example","format":"problem-workspace","prompt":"Choose scales for position data from 0 to 1.10 m over 0 to 2.0 s, using 30 squares across and 20 up.","given":"Both axes start at zero. Time goes across; position goes up.","equation":"Minimum step = data range ÷ number of squares. Check: squares × chosen step ≥ data range.","work":"Time: 2.0 s ÷ 30 ≈ 0.067 s per square → choose 0.1 s per square. Check: 30 × 0.1 s = 3.0 s.\n\nPosition: 1.10 m ÷ 20 = 0.055 m per square → choose 0.1 m per square. Check: 20 × 0.1 m = 2.0 m.\n\nLabel the axes t (s) and x (m). At t = 1.2 s and x = 0.47 m, the point is 12 squares across and 4.7 squares up.","answer":"Use 0.1 s per horizontal square and 0.1 m per vertical square. Each axis has a uniform scale, and all values fit.","workshop":{"stage":"See it worked","pageBreakBefore":true}},{"id":"check-fmjVsKsU9Sw","type":"question","capture":true,"targetId":"foundations.graph-scales","evidenceRole":"practice","sei":{"visual":{"src":"/learning/video-graph-scale.svg","alt":"A reference graph with time on the horizontal axis, position on the vertical axis, and equal steps along each axis."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["axis","range","scale","uniform interval","coordinate"],"modes":["text","sketch"]},"workshop":{"stage":"Check your thinking","pageBreakBefore":true},"question":{"prompt":"Your velocity data runs from 0 to 3.4 m/s. The vertical axis has 20 squares and starts at zero. Which scale is the smallest of these choices that fits all the data?","options":[{"id":"A","text":"0.1 m/s per square","feedback":"This only reaches 2.0 m/s, so some data would fall off the graph."},{"id":"B","text":"0.2 m/s per square","feedback":"20 × 0.2 m/s = 4.0 m/s, which fits 3.4 m/s and uses more space than the larger scale."},{"id":"C","text":"0.5 m/s per square","feedback":"This fits, but reaches 10 m/s and squeezes the data into less of the page."}],"correctOptionId":"B"}},{"id":"check-fmjVsKsU9Sw-2","type":"question","capture":true,"targetId":"foundations.graph-scales","evidenceRole":"practice","sei":{"visual":{"src":"/learning/video-graph-scale.svg","alt":"A reference graph with time on the horizontal axis, position on the vertical axis, and equal steps along each axis."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["axis","range","scale","uniform interval","coordinate"],"modes":["text","sketch"]},"question":{"prompt":"A time axis has equally spaced lines labeled 0, 1, 2, 4, and 8 s. What needs to change?","options":[{"id":"A","text":"Nothing: the labels increase.","feedback":"Increasing values alone do not make a uniform scale."},{"id":"B","text":"The position axis must use the same numbers.","feedback":"The two axes measure different quantities and can use different scales."},{"id":"C","text":"Equal spaces on the time axis must represent equal time intervals.","feedback":"On a uniform scale, every equal step represents the same time interval."}],"correctOptionId":"C"}},{"id":"explain-fmjVsKsU9Sw","type":"exit_ticket","capture":true,"targetId":"foundations.graph-scales","evidenceRole":"exit","prompt":"New data runs from 0 to 4.6 s and 0 to 2.3 m. Your graph has 25 squares across and 20 up, with both axes starting at zero. Choose a scale for each axis using steps of 1, 2, or 5 times a power of ten. Show both divisions and both checks that the data fits. Label each axis with its quantity and unit. Then state how many squares across and up you would plot the point (2.4 s, 1.6 m).","sei":{"visual":{"src":"/learning/video-graph-scale.svg","alt":"A reference graph with time on the horizontal axis, position on the vertical axis, and equal steps along each axis."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["axis","range","scale","uniform interval","coordinate"],"modes":["text","sketch"]},"workshop":{"stage":"Apply & explain","pageBreakBefore":true}}]}},{"youtubeId":"lZIZ8jByakc","sequence":10,"lessonId":"f3d4122a-5bbe-47c9-86da-ad8cccd6df57","target":{"id":"f6ab3a25-e6a7-473f-b5b5-83b7dd5716b3","slug":"foundations.scientific-notation","statement":"I can write measurements in scientific notation and compare their sizes using coefficients and powers of ten.","domain":"skill","unit_id":"unit-1","program":"physics","content_strand":"foundations","order_index":10},"title":"Powers of ten & scientific notation","slug":"video-10-powers-of-ten-scientific-notation","duration":248,"description":"How can you write and compare huge and tiny measurements without counting long strings of zeros?","document":{"schemaVersion":1,"presentation":"physics-path","dayType":"STANDARD","learningPath":{"version":1,"kind":"lesson","focus":"How can you write and compare huge and tiny measurements without counting long strings of zeros?","targetSlugs":["foundations.scientific-notation"],"foundations":true},"blocks":[{"id":"video-lZIZ8jByakc","type":"instruction_video","youtubeId":"lZIZ8jByakc","title":"Powers of ten & scientific notation","summary":"Each increase of one in a power of ten multiplies the value by ten. Zero as an exponent gives one; a negative exponent represents a reciprocal, not a negative quantity. Write a positive measurement as a coefficient from 1 up to, but not including, 10 times a power of ten, retaining its unit. Compare values using both coefficients and exponents.","durationSeconds":248,"targetId":"foundations.scientific-notation","workshop":{"stage":"Watch & understand","pageBreakBefore":true}},{"id":"scope-lZIZ8jByakc","type":"prose","markdown":"Write positive measured quantities in normalized scientific notation and compare their sizes."},{"id":"vocabulary-lZIZ8jByakc","type":"vocab","terms":[{"term":"power of ten","definition":"A number written as 10 raised to an exponent; each increase of one in the exponent multiplies its value by ten."},{"term":"scientific notation","definition":"A way to write a nonzero number as a coefficient with magnitude at least 1 and less than 10, multiplied by a power of ten."},{"term":"coefficient","definition":"The number multiplying the power of ten in scientific notation."},{"term":"exponent","definition":"The power applied to a base; a negative exponent means the reciprocal of the corresponding positive power."}],"referencePanel":true},{"id":"worked-lZIZ8jByakc","type":"worked_example","format":"problem-workspace","prompt":"Write 4 200 000 m and 0.0036 s in scientific notation.","given":"Keep the quantity and unit unchanged. For these positive numbers, the coefficient must be at least 1 and less than 10.","equation":"Quantity = coefficient × 10ⁿ × unit.","work":"4 200 000 m = 4.2 × 10⁶ m. Moving the decimal six places left gives 4.2; 10⁶ supplies the factor of one million.\n\n0.0036 s = 3.6 × 10⁻³ s. Moving the decimal three places right gives 3.6; 10⁻³ means divide by one thousand.","answer":"4.2 × 10⁶ m and 3.6 × 10⁻³ s. A negative exponent does not make the time negative; it gives a positive fraction of a second.","workshop":{"stage":"See it worked","pageBreakBefore":true}},{"id":"check-lZIZ8jByakc","type":"question","capture":true,"targetId":"foundations.scientific-notation","evidenceRole":"practice","sei":{"visual":{"src":"/learning/video-scientific-notation.svg","alt":"Scientific notation has a coefficient, a power of ten, and a unit. Negative powers of ten describe small positive values."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["power of ten","scientific notation","coefficient","exponent"],"modes":["text","sketch"]},"workshop":{"stage":"Check your thinking","pageBreakBefore":true},"question":{"prompt":"Which is the correct scientific notation for 0.00068 m?","options":[{"id":"A","text":"6.8 × 10⁴ m","feedback":"A positive exponent here makes the number much larger than one."},{"id":"B","text":"6.8 × 10⁻⁴ m","feedback":"Moving the decimal four places gives 6.8; multiplying by 10⁻⁴ restores the original small value."},{"id":"C","text":"68 × 10⁻⁴ m","feedback":"This equals 0.0068 m, and the coefficient is not between 1 and 10."}],"correctOptionId":"B"}},{"id":"check-lZIZ8jByakc-2","type":"question","capture":true,"targetId":"foundations.scientific-notation","evidenceRole":"practice","sei":{"visual":{"src":"/learning/video-scientific-notation.svg","alt":"Scientific notation has a coefficient, a power of ten, and a unit. Negative powers of ten describe small positive values."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["power of ten","scientific notation","coefficient","exponent"],"modes":["text","sketch"]},"question":{"prompt":"One distance is 6 × 10⁷ m. Another is 2 × 10⁵ m. How many times larger is the first?","options":[{"id":"A","text":"3 times","feedback":"That compares the coefficients but ignores the different powers of ten."},{"id":"B","text":"100 times","feedback":"That compares the powers of ten but ignores the factor of three between the coefficients."},{"id":"C","text":"300 times","feedback":"(6 ÷ 2) × 10⁷⁻⁵ = 3 × 10² = 300."}],"correctOptionId":"C"}},{"id":"explain-lZIZ8jByakc","type":"exit_ticket","capture":true,"targetId":"foundations.scientific-notation","evidenceRole":"exit","prompt":"Write 7 200 000 m and 0.00045 s in scientific notation. Explain the sign of each exponent. Then compare two distances: 9 × 10⁶ m and 3 × 10⁴ m. How many times larger is the first? Show how you used both the coefficients and the powers of ten.","sei":{"visual":{"src":"/learning/video-scientific-notation.svg","alt":"Scientific notation has a coefficient, a power of ten, and a unit. Negative powers of ten describe small positive values."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["power of ten","scientific notation","coefficient","exponent"],"modes":["text","sketch"]},"workshop":{"stage":"Apply & explain","pageBreakBefore":true}}]}},{"youtubeId":"VQlq7_OtDF8","sequence":11,"lessonId":"a1f76a24-a97b-4f44-a77f-793b99303e00","target":{"id":"e3ad1eaa-5d17-4012-86eb-9a0fd1dcdcf7","slug":"foundations.metric-prefixes","statement":"I can read SI units and metric prefixes and express the same measurement with different prefixes.","domain":"knowledge","unit_id":"unit-1","program":"physics","content_strand":"foundations","order_index":11},"title":"The SI system & metric prefixes","slug":"video-11-the-si-system-metric-prefixes","duration":238,"description":"What does a prefix change about a measurement, and why does a capital letter matter?","document":{"schemaVersion":1,"presentation":"physics-path","dayType":"STANDARD","learningPath":{"version":1,"kind":"lesson","focus":"What does a prefix change about a measurement, and why does a capital letter matter?","targetSlugs":["foundations.metric-prefixes"],"foundations":true},"blocks":[{"id":"video-VQlq7_OtDF8","type":"instruction_video","youtubeId":"VQlq7_OtDF8","title":"The SI system & metric prefixes","summary":"SI gives scientists a shared measurement system. Mechanics commonly uses meters, kilograms, and seconds. A prefix multiplies a unit by a power of ten: kilo means 10³, milli means 10⁻³, micro means 10⁻⁶, and nano means 10⁻⁹. Symbols are case-sensitive: M means mega, while m as a prefix means milli. Convert between prefixes without changing the physical quantity.","durationSeconds":238,"targetId":"foundations.metric-prefixes","workshop":{"stage":"Watch & understand","pageBreakBefore":true}},{"id":"scope-VQlq7_OtDF8","type":"prose","markdown":"Read SI unit symbols and metric prefixes, including case, and express equivalent measurements."},{"id":"vocabulary-VQlq7_OtDF8","type":"vocab","terms":[{"term":"SI","definition":"The International System of Units, a shared system for reporting physical measurements."},{"term":"base unit","definition":"One of the seven SI units used to build other units; mechanics commonly uses the meter, kilogram, and second."},{"term":"metric prefix","definition":"A symbol placed before a unit to multiply it by a stated power of ten."},{"term":"kilo","definition":"The prefix k, meaning one thousand, or 10³."},{"term":"milli","definition":"The prefix m, meaning one thousandth, or 10⁻³."},{"term":"micro","definition":"The prefix µ, meaning one millionth, or 10⁻⁶."}],"referencePanel":true},{"id":"worked-VQlq7_OtDF8","type":"worked_example","format":"problem-workspace","prompt":"Express 3.2 km and 0.45 mm in meters.","given":"kilo (k) = 10³; milli (m as a prefix) = 10⁻³. The symbol m on its own is the meter.","equation":"Replace the prefix with its power of ten, keeping the unit.","work":"3.2 km = 3.2 × 10³ m = 3 200 m.\n\n0.45 mm = 0.45 × 10⁻³ m = 0.00045 m = 4.5 × 10⁻⁴ m.","answer":"3 200 m and 0.00045 m. A prefix changes the size of the unit and the numerical value, while the measured length stays the same.","workshop":{"stage":"See it worked","pageBreakBefore":true}},{"id":"check-VQlq7_OtDF8","type":"question","capture":true,"targetId":"foundations.metric-prefixes","evidenceRole":"practice","sei":{"visual":{"src":"/learning/video-metric-prefixes.svg","alt":"Reference: giga 10⁹, mega 10⁶, kilo 10³, no prefix 10⁰, milli 10⁻³, micro 10⁻⁶, nano 10⁻⁹."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["SI","base unit","metric prefix","kilo","milli","micro"],"modes":["text","sketch"]},"workshop":{"stage":"Check your thinking","pageBreakBefore":true},"question":{"prompt":"A timer reads 2 500 µs. Since 1 ms = 1 000 µs, what is the same time in milliseconds?","options":[{"id":"A","text":"2 500 000 ms","feedback":"Milliseconds are larger than microseconds, so the numerical value must get smaller."},{"id":"B","text":"0.0025 ms","feedback":"This is the value in seconds, not milliseconds."},{"id":"C","text":"2.5 ms","feedback":"2 500 µs ÷ 1 000 µs per ms = 2.5 ms."}],"correctOptionId":"C"}},{"id":"check-VQlq7_OtDF8-2","type":"question","capture":true,"targetId":"foundations.metric-prefixes","evidenceRole":"practice","sei":{"visual":{"src":"/learning/video-metric-prefixes.svg","alt":"Reference: giga 10⁹, mega 10⁶, kilo 10³, no prefix 10⁰, milli 10⁻³, micro 10⁻⁶, nano 10⁻⁹."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["SI","base unit","metric prefix","kilo","milli","micro"],"modes":["text","sketch"]},"question":{"prompt":"Compare 5 Mm and 5 mm. Which statement is correct?","options":[{"id":"A","text":"5 Mm is one billion times as long as 5 mm.","feedback":"Mega is 10⁶ and milli is 10⁻³. Their ratio is 10⁹."},{"id":"B","text":"They are equal because capitalization does not matter.","feedback":"SI prefix symbols are case-sensitive: M and m have different meanings."},{"id":"C","text":"5 Mm is one thousand times as long as 5 mm.","feedback":"The exponent difference is 6 − (−3) = 9, not 3."}],"correctOptionId":"A"}},{"id":"explain-VQlq7_OtDF8","type":"exit_ticket","capture":true,"targetId":"foundations.metric-prefixes","evidenceRole":"exit","prompt":"Convert 0.62 km to meters and 4 800 µs to milliseconds. Show the prefix powers or conversion factors you used. Then explain why writing 2 Mm instead of 2 mm changes the reported length so much. State which symbol means mega and which means milli.","sei":{"visual":{"src":"/learning/video-metric-prefixes.svg","alt":"Reference: giga 10⁹, mega 10⁶, kilo 10³, no prefix 10⁰, milli 10⁻³, micro 10⁻⁶, nano 10⁻⁹."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["SI","base unit","metric prefix","kilo","milli","micro"],"modes":["text","sketch"]},"workshop":{"stage":"Apply & explain","pageBreakBefore":true}}]}},{"youtubeId":"SE8M273AKXw","sequence":12,"lessonId":"674a0a1f-9b87-4e06-93c0-2fcc14bda8fb","target":{"id":"1f32a778-2fb3-48f0-a9ca-6713a1583829","slug":"foundations.unit-conversions","statement":"I can use conversion factors to convert lengths, times, and rates, showing unit cancellation and checking the result.","domain":"skill","unit_id":"unit-1","program":"physics","content_strand":"foundations","order_index":12},"title":"Unit conversions: one step, two steps & rates","slug":"video-12-unit-conversions-one-step-two-steps-rates","duration":264,"description":"How can unit cancellation tell you which conversion factors to use?","document":{"schemaVersion":1,"presentation":"physics-path","dayType":"STANDARD","learningPath":{"version":1,"kind":"lesson","focus":"How can unit cancellation tell you which conversion factors to use?","targetSlugs":["foundations.unit-conversions"],"foundations":true},"blocks":[{"id":"video-SE8M273AKXw","type":"instruction_video","youtubeId":"SE8M273AKXw","title":"Unit conversions: one step, two steps & rates","summary":"A conversion factor is a ratio of equal quantities, so its value is one. Orient each factor so the unwanted unit cancels. Chain factors when a conversion needs more than one step. For rates, convert the numerator and denominator units, then check both the remaining unit and whether the size of the result makes sense.","durationSeconds":264,"targetId":"foundations.unit-conversions","workshop":{"stage":"Watch & understand","pageBreakBefore":true}},{"id":"scope-SE8M273AKXw","type":"prose","markdown":"Use conversion factors for lengths, times, and rates, showing cancellation and checking equivalent values."},{"id":"vocabulary-SE8M273AKXw","type":"vocab","terms":[{"term":"conversion factor","definition":"A ratio of equal quantities in different units; its value is one."},{"term":"unit cancellation","definition":"Removing matching unit factors from the numerator and denominator of a calculation."},{"term":"equivalent quantities","definition":"Measurements that describe the same amount even when their numbers and units differ."},{"term":"rate","definition":"A ratio comparing one quantity with another, such as distance per unit of time."}],"referencePanel":true},{"id":"worked-SE8M273AKXw","type":"worked_example","format":"problem-workspace","prompt":"Convert 2.0 h to seconds, then convert 36 km/h to m/s.","given":"1 h = 60 min; 1 min = 60 s; 1 km = 1 000 m.","equation":"Multiply by ratios of equal quantities. Put each unwanted unit on the opposite side of the next fraction.","work":"2.0 h × (60 min / 1 h) × (60 s / 1 min) = 7 200 s. Hours and then minutes cancel.\n\n36 km/h × (1 000 m / 1 km) × (1 h / 3 600 s) = 10 m/s. Kilometers and hours cancel.","answer":"2.0 h = 7 200 s and 36 km/h = 10 m/s. The numerical values change, but each converted quantity is physically equal to the original.","workshop":{"stage":"See it worked","pageBreakBefore":true}},{"id":"check-SE8M273AKXw","type":"question","capture":true,"targetId":"foundations.unit-conversions","evidenceRole":"practice","sei":{"visual":{"src":"/learning/video-unit-conversions.svg","alt":"To change kilometers to meters, multiply by 1 000 meters over 1 kilometer. The kilometer units cancel and meters remain."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["conversion factor","unit cancellation","equivalent quantities","rate"],"modes":["text","sketch"]},"workshop":{"stage":"Check your thinking","pageBreakBefore":true},"question":{"prompt":"You want to change 3.5 min into seconds. Which multiplication cancels minutes and leaves seconds?","options":[{"id":"A","text":"3.5 min × (1 min / 60 s)","feedback":"Minutes would not cancel; you would get min²/s."},{"id":"B","text":"3.5 min × (60 s / 1 min)","feedback":"The minutes cancel, leaving 3.5 × 60 = 210 s."},{"id":"C","text":"3.5 min × (60 min / 1 s)","feedback":"This uses the wrong equality and leaves min²/s."}],"correctOptionId":"B"}},{"id":"check-SE8M273AKXw-2","type":"question","capture":true,"targetId":"foundations.unit-conversions","evidenceRole":"practice","sei":{"visual":{"src":"/learning/video-unit-conversions.svg","alt":"To change kilometers to meters, multiply by 1 000 meters over 1 kilometer. The kilometer units cancel and meters remain."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["conversion factor","unit cancellation","equivalent quantities","rate"],"modes":["text","sketch"]},"question":{"prompt":"A cart moves at 54 km/h. What is the same speed in m/s? Use 1 km = 1 000 m and 1 h = 3 600 s.","options":[{"id":"A","text":"15 m/s","feedback":"54 × 1 000 ÷ 3 600 = 15 m/s. Both the distance unit and the time unit must change."},{"id":"B","text":"194.4 m/s","feedback":"That multiplies by 3.6 instead of dividing by 3.6."},{"id":"C","text":"54 000 m/s","feedback":"That converts kilometers but leaves the time unit as hours."}],"correctOptionId":"A"}},{"id":"explain-SE8M273AKXw","type":"exit_ticket","capture":true,"targetId":"foundations.unit-conversions","evidenceRole":"exit","prompt":"Convert 2.5 min to seconds and 90 km/h to m/s. Write each conversion as multiplication by fractions and show which units cancel. A classmate converts 90 km/h to 90 000 m/s by changing only kilometers to meters. Explain the missing step and how you can check your own result.","sei":{"visual":{"src":"/learning/video-unit-conversions.svg","alt":"To change kilometers to meters, multiply by 1 000 meters over 1 kilometer. The kilometer units cancel and meters remain."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["conversion factor","unit cancellation","equivalent quantities","rate"],"modes":["text","sketch"]},"workshop":{"stage":"Apply & explain","pageBreakBefore":true}}]}}]$payload$::jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('physics-video-additions-2026-09-30'));
 SELECT md5(coalesce(jsonb_agg(to_jsonb(w) ORDER BY w.id)::text,'')) INTO windows_before FROM public.lesson_class_windows w;
 SELECT md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id)::text,'')) INTO old_lessons_before FROM public.lessons x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(additions) a WHERE (a->>'lessonId')::uuid=x.id);
 FOR item IN SELECT value FROM jsonb_array_elements(additions) LOOP
  target:=item->'target';
  INSERT INTO public.learning_targets(id,slug,statement,domain,unit_id,program,content_strand,order_index,lesson_id)
  VALUES((target->>'id')::uuid,target->>'slug',target->>'statement',target->>'domain','unit-1','physics','foundations',(target->>'order_index')::integer,item->>'lessonId') ON CONFLICT(slug) DO NOTHING;
  SELECT * INTO STRICT found_target FROM public.learning_targets WHERE slug=target->>'slug';
  IF found_target.statement<>target->>'statement' OR found_target.domain<>target->>'domain' OR found_target.unit_id<>'unit-1' OR found_target.program<>'physics' THEN RAISE EXCEPTION 'Target changed: %',target->>'slug'; END IF;
  SELECT id INTO existing_id FROM public.lessons WHERE content_blocks->>'presentation'='physics-path' AND content_blocks->'blocks' @> jsonb_build_array(jsonb_build_object('type','instruction_video','youtubeId',item->>'youtubeId')) LIMIT 1;
  IF existing_id IS NOT NULL AND existing_id<>(item->>'lessonId')::uuid THEN RAISE EXCEPTION 'Video already has a different lesson: %',item->>'youtubeId'; END IF;
  INSERT INTO public.lessons(id,title,slug,unit_id,unit,lesson_number,lesson_type,published,estimated_time,description,objectives,content_blocks)
  VALUES((item->>'lessonId')::uuid,item->>'title',item->>'slug','unit-1',(SELECT name FROM public.units WHERE id='unit-1'),99+(item->>'sequence')::integer,'video',true,18,item->>'description',ARRAY[target->>'slug'],item->'document') ON CONFLICT(id) DO NOTHING;
  SELECT * INTO STRICT l FROM public.lessons WHERE id=(item->>'lessonId')::uuid FOR UPDATE;
  IF l.unit_id<>'unit-1' OR l.content_blocks->>'presentation'<>'physics-path' OR NOT l.content_blocks->'learningPath'->'targetSlugs' ? (target->>'slug') OR NOT l.content_blocks->'blocks' @> jsonb_build_array(jsonb_build_object('type','instruction_video','youtubeId',item->>'youtubeId')) THEN RAISE EXCEPTION 'Lesson changed: %',l.id; END IF;
  INSERT INTO public.lesson_video_catalog(youtube_id,duration_seconds) VALUES(item->>'youtubeId',(item->>'duration')::integer) ON CONFLICT(youtube_id) DO NOTHING;
  IF NOT EXISTS(SELECT 1 FROM public.lesson_video_catalog WHERE youtube_id=item->>'youtubeId' AND duration_seconds=(item->>'duration')::integer) THEN RAISE EXCEPTION 'Video duration changed'; END IF;
  SELECT id INTO set_id FROM public.vocabulary_sets WHERE lesson_id=l.id::text;
  IF set_id IS NULL THEN
   SELECT jsonb_agg(t||jsonb_build_object('tier',3)) INTO terms FROM jsonb_array_elements(item->'document'->'blocks') b CROSS JOIN LATERAL jsonb_array_elements(coalesce(b->'terms','[]'::jsonb)) t WHERE b->>'type'='vocab';
   result:=public.save_lesson_vocabulary(l.id,null,terms,true);set_id:=(result->>'setId')::uuid;
   SELECT jsonb_agg(id ORDER BY order_index) INTO ids FROM public.vocabulary_terms WHERE vocabulary_set_id=set_id AND NOT archived;
   SELECT jsonb_agg(CASE WHEN b->>'type'='vocab' THEN b||jsonb_build_object('terms','[]'::jsonb,'termIds',ids,'vocabularySetId',set_id) ELSE b END ORDER BY ord) INTO blocks FROM jsonb_array_elements(l.content_blocks->'blocks') WITH ORDINALITY a(b,ord);
   UPDATE public.lessons SET content_blocks=jsonb_set(content_blocks,'{blocks}',blocks),updated_at=now() WHERE id=l.id;
  END IF;
  INSERT INTO public.vocab_target_terms(target_id,term_id) SELECT found_target.id,id FROM public.vocabulary_terms WHERE vocabulary_set_id=set_id AND NOT archived ON CONFLICT DO NOTHING;
 END LOOP;
 IF windows_before IS DISTINCT FROM (SELECT md5(coalesce(jsonb_agg(to_jsonb(w) ORDER BY w.id)::text,'')) FROM public.lesson_class_windows w) THEN RAISE EXCEPTION 'Class releases changed; retry without changing access'; END IF;
 IF old_lessons_before IS DISTINCT FROM (SELECT md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id)::text,'')) FROM public.lessons x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(additions) a WHERE (a->>'lessonId')::uuid=x.id)) THEN RAISE EXCEPTION 'An existing lesson changed; no additions saved'; END IF;
END $install$;
